(53, 8, 'source_snapshot', 'Frontend Source Snapshot', 'source', 0, 'reference', 1, 0, '{\"source_file\":\"news-article.php\",\"meta\":{\"pageTitle\":\"Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate | Trans-Nzoia County\",\"pageDescription\":\"Trans-Nzoia AHP delivers first 200 housing units at Maili Tatu Estate â€” beneficiaries receive keys in landmark handover ceremony presided over by Governor George Natembeya.\",\"pageKeywords\":\"Maili Tatu Estate, Kitale affordable housing, Trans-Nzoia AHP, housing handover, Governor Natembeya, affordable housing Kenya\",\"canonicalUrl\":\"https://housing.transnzoia.go.ke/news-article.php\",\"activePage\":\"news\"},\"headings\":[{\"level\":1,\"text\":\"Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate — Beneficiaries Receive Keys\"},{\"level\":2,\"text\":\"About the Maili Tatu Estate Project\"},{\"level\":2,\"text\":\"Beneficiary Selection Process\"},{\"level\":2,\"text\":\"More from News & Updates\"},{\"level\":3,\"text\":\"Endebess Phase 2 Ground-Breaking Ceremony Marks Start of Construction for 320 New Units\"},{\"level\":3,\"text\":\"CS Hinga Announces KSh 450M Additional Allocation for Trans-Nzoia AHP\"},{\"level\":3,\"text\":\"Saboti Constituency Beneficiary Registration Opens â€” Over 1,200 Apply in First Week\"}],\"sections\":[{\"order\":1,\"id\":\"\",\"class\":\"article-hero\",\"aria_label\":\"Article header\",\"labelled_by\":\"\"},{\"order\":2,\"id\":\"\",\"class\":\"article-related-section\",\"aria_label\":\"More articles\",\"labelled_by\":\"\"}],\"images\":[{\"src\":\"uploads/news/featured-maili-tatu.jpg\",\"alt\":\"Beneficiaries receive housing unit keys at Maili Tatu Estate handover ceremony\",\"loading\":\"eager\"},{\"src\":\"uploads/news/maili-tatu-construction.jpg\",\"alt\":\"Aerial view of Maili Tatu Estate construction progress showing completed Blocks Aâ€“E and ongoing works on Block F\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/endebess-groundbreaking.jpg\",\"alt\":\"Endebess Phase 2 ground-breaking\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/policy-affordable-housing.jpg\",\"alt\":\"Affordable housing policy\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/community-engagement.jpg\",\"alt\":\"Community engagement session\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/endebess-groundbreaking.jpg\",\"alt\":\"Endebess Phase 2 ground-breaking ceremony\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/policy-affordable-housing.jpg\",\"alt\":\"CS Hinga at AHP policy briefing\",\"loading\":\"lazy\"},{\"src\":\"uploads/news/community-engagement.jpg\",\"alt\":\"Community beneficiary registration session\",\"loading\":\"lazy\"}],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"news.php\",\"text\":\"News & Updates\"},{\"href\":\"news.php?category=programme-updates\",\"text\":\"Programme Updates\"},{\"href\":\"news.php?category=community\",\"text\":\"Community\"},{\"href\":\"news.php?category=official\",\"text\":\"Official\"},{\"href\":\"news.php\",\"text\":\"Maili Tatu Estate\"},{\"href\":\"news.php\",\"text\":\"Kitale\"},{\"href\":\"news.php\",\"text\":\"Housing Handover\"},{\"href\":\"news-article.php\",\"text\":\"Previous Article\\r\\n                \\r\\n                Endebess Phase 2 Ground-Breaking Ceremony Marks Start of Construction\\r\\n                Groundbreaking\"},{\"href\":\"news-article.php\",\"text\":\"Next Article \\r\\n                \\r\\n                CS Hinga Announces KSh 450M Additional Allocation for Trans-Nzoia AHP\\r\\n                Policy\"},{\"href\":\"projects.php\",\"text\":\"View Full Project\"},{\"href\":\"news-article.php\",\"text\":\"Groundbreaking\\r\\n                    Endebess Phase 2 Ground-Breaking Marks Start of Construction\"},{\"href\":\"news-article.php\",\"text\":\"Policy\\r\\n                    CS Hinga Announces KSh 450M Additional Allocation for Trans-Nzoia\"},{\"href\":\"news-article.php\",\"text\":\"Community\\r\\n                    Saboti Constituency Beneficiary Registration Opens â€” Over 1,200 Apply in First Week\"},{\"href\":\"news.php\",\"text\":\"All Articles\"},{\"href\":\"news-article.php\",\"text\":\"Read Article\"},{\"href\":\"news-article.php\",\"text\":\"Read Article\"},{\"href\":\"news-article.php\",\"text\":\"Read Article\"}],\"html_snapshot\":\"﻿<?php\\n$basePath = \'\';\\n$activePage = \'news\';\\n$pageTitle = \'Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate | Trans-Nzoia County\';\\n$pageDescription = \'Trans-Nzoia AHP delivers first 200 housing units at Maili Tatu Estate â€” beneficiaries receive keys in landmark handover ceremony presided over by Governor George Natembeya.\';\\n$pageKeywords = \'Maili Tatu Estate, Kitale affordable housing, Trans-Nzoia AHP, housing handover, Governor Natembeya, affordable housing Kenya\';\\n$pageAuthor = \'Trans-Nzoia County Government â€” Department of Land, Housing & Physical Planning\';\\n$pageRobots = \'index, follow\';\\n$themeColor = \'#163300\';\\n$canonicalUrl = \'https://housing.transnzoia.go.ke/news-article.php\';\\n$pageStyles = [\\n  \'assets/css/global.css\',\\n  \'assets/css/pages/news.css\',\\n  \'assets/css/pages/news-article.css\'\\n];\\n$pageScripts = [\\n  \'assets/js/global.js\',\\n  \'assets/js/pages/news-article.js\'\\n];\\n$headMeta = [\\n  \'<meta property=\\\"og:title\\\" content=\\\"Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate\\\">\',\\n  \'<meta property=\\\"og:description\\\" content=\\\"Beneficiaries receive keys in landmark handover ceremony presided over by Governor George Natembeya at Maili Tatu Estate, Kitale.\\\">\',\\n  \'<meta property=\\\"og:type\\\" content=\\\"article\\\">\',\\n  \'<meta property=\\\"og:url\\\" content=\\\"https://housing.transnzoia.go.ke/news-article.php\\\">\',\\n  \'<meta property=\\\"og:image\\\" content=\\\"uploads/news/featured-maili-tatu.jpg\\\">\',\\n  \'<meta property=\\\"og:locale\\\" content=\\\"en_KE\\\">\',\\n  \'<meta property=\\\"og:site_name\\\" content=\\\"Trans-Nzoia AHP Tracker\\\">\',\\n  \'<meta property=\\\"article:published_time\\\" content=\\\"2026-05-15T08:00:00+03:00\\\">\',\\n  \'<meta property=\\\"article:section\\\" content=\\\"Programme Updates\\\">\',\\n  \'<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\">\',\\n  \'<meta name=\\\"twitter:title\\\" content=\\\"Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate\\\">\',\\n  \'<meta name=\\\"twitter:description\\\" content=\\\"Beneficiaries receive keys in landmark ceremony presided over by Governor George Natembeya.\\\">\',\\n  \'<meta name=\\\"twitter:image\\\" content=\\\"uploads/news/featured-maili-tatu.jpg\\\">\'\\n];\\ninclude __DIR__ . \\\"/app/partials/\\\" . \'head.php\';\\n?>\\n<body>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'cursor.php\'; ?>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'skip-link.php\'; ?>\\n<?php include __DIR__ . \\\"/app/partials/\\\" . \'navbar.php\'; ?><main id=\\\"main-content\\\">\\r\\n\\r\\n    <!-- ===== ARTICLE HERO ===== -->\\r\\n    <section class=\\\"article-hero\\\" aria-label=\\\"Article header\\\">\\r\\n      <div class=\\\"article-hero-bg\\\" aria-hidden=\\\"true\\\"></div>\\r\\n      <div class=\\\"article-hero-glow\\\" aria-hidden=\\\"true\\\"></div>\\r\\n\\r\\n      <div class=\\\"container\\\">\\r\\n        <!-- Breadcrumb -->\\r\\n        <nav class=\\\"breadcrumb\\\" aria-label=\\\"Breadcrumb\\\">\\r\\n          <a href=\\\"index.php\\\" class=\\\"breadcrumb-link\\\">Home</a>\\r\\n          <span class=\\\"breadcrumb-sep\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-chevron-right\\\"></i></span>\\r\\n          <a href=\\\"news.php\\\" class=\\\"breadcrumb-link\\\">News &amp; Updates</a>\\r\\n          <span class=\\\"breadcrumb-sep\\\" aria-hidden=\\\"true\\\"><i class=\\\"fa-solid fa-chevron-right\\\"></i></span>\\r\\n          <span class=\\\"breadcrumb-current\\\" aria-current=\\\"page\\\">Trans-Nzoia AHP Delivers First 200 Units&hellip;</span>\\r\\n        </nav>\\r\\n\\r\\n        <!-- â”€â”€ Two-column hero layout â”€â”€ -->\\r\\n        <div class=\\\"article-hero-layout\\\">\\r\\n\\r\\n          <!-- LEFT: Article content -->\\r\\n          <div class=\\\"article-hero-content\\\">\\r\\n            <h1 class=\\\"article-headline\\\">Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate &mdash; Beneficiaries Receive Keys</h1>\\r\\n\\r\\n            <p class=\\\"article-deck\\\">Governor George Natembeya presided over the formal delivery of 200 completed affordable housing units to qualifying beneficiaries &mdash; marking the programme&rsquo;s most significant milestone to date in Trans-Nzoia County.</p>\\r\\n\\r\\n            <div class=\\\"article-meta\\\" aria-label=\\\"Article information\\\">\\r\\n              <span class=\\\"article-meta-item is-author\\\">\\r\\n                <i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                Dept. of Land, Housing &amp; Physical Planning\\r\\n              </span>\\r\\n              <span class=\\\"article-meta-divider\\\" aria-hidden=\\\"true\\\"></span>\\r\\n              <span class=\\\"article-meta-item\\\">\\r\\n                <i class=\\\"fa-regular fa-calendar\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                <time datetime=\\\"2026-05-15\\\">15 May 2026</time>\\r\\n              </span>\\r\\n              <span class=\\\"article-meta-divider\\\" aria-hidden=\\\"true\\\"></span>\\r\\n              <span class=\\\"article-meta-item\\\">\\r\\n                <i class=\\\"fa-regular fa-clock\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                <span id=\\\"articleReadTime\\\">6 min read</span>\\r\\n              </span>\\r\\n            </div>\\r\\n\\r\\n          </div><!-- /article-hero-content -->\\r\\n\\r\\n          <!-- RIGHT: Featured image -->\\r\\n          <div class=\\\"article-hero-media\\\" aria-label=\\\"Article featured image\\\">\\r\\n            <div class=\\\"article-hero-img-frame\\\">\\r\\n              <div class=\\\"article-hero-img-ph\\\" aria-hidden=\\\"true\\\">\\r\\n                <div class=\\\"article-hero-img-ph-inner\\\">\\r\\n                  <i class=\\\"fa-solid fa-city\\\"></i>\\r\\n                  <span>Maili Tatu Estate<br>Kitale, Trans-Nzoia</span>\\r\\n                </div>\\r\\n              </div>\\r\\n              <img src=\\\"uploads/news/featured-maili-tatu.jpg\\\"\\r\\n                   alt=\\\"Beneficiaries receive housing unit keys at Maili Tatu Estate handover ceremony\\\"\\r\\n                   loading=\\\"eager\\\"\\r\\n                   onerror=\\\"this.style.display=\'none\'\\\">\\r\\n            </div>\\r\\n            <div class=\\\"article-hero-media-caption\\\">\\r\\n              <i class=\\\"fa-solid fa-camera\\\" aria-hidden=\\\"true\\\"></i>\\r\\n              Governor Natembeya hands keys to the first beneficiary at Maili Tatu Estate, Kitale &mdash; 15 May 2026. Photo: Trans-Nzoia County Communications.\\r\\n            </div>\\r\\n          </div><!-- /article-hero-media -->\\r\\n\\r\\n        </div><!-- /article-hero-layout -->\\r\\n      </div><!-- /container -->\\r\\n\\r\\n    </section><!-- /article-hero -->\\r\\n\\r\\n    <!-- ===== ARTICLE BODY ===== -->\\r\\n    <div class=\\\"article-body-wrap\\\">\\r\\n      <div class=\\\"container\\\">\\r\\n        <div class=\\\"article-layout\\\">\\r\\n\\r\\n          <!-- â”€â”€ MAIN PROSE COLUMN â”€â”€ -->\\r\\n          <div>\\r\\n            <article class=\\\"article-prose\\\" id=\\\"articleContent\\\">\\r\\n\\r\\n              <p>The Trans-Nzoia County Affordable Housing Programme reached a defining milestone on 15 May 2026 when Governor George Natembeya formally handed over the keys to 200 completed housing units at the Maili Tatu Estate in Kitale. The ceremony, attended by Cabinet Secretary for Housing Charles Hinga, Members of the County Assembly, and hundreds of jubilant beneficiaries, marked the first mass delivery of finished units under the programme since its inception in 2023.</p>\\r\\n\\r\\n              <p>The units &mdash; a mix of one-bedroom and two-bedroom typologies spread across Blocks A to E of the estate &mdash; were delivered ahead of the original June 2026 schedule, a development the Governor attributed to strict contractor supervision and the county&rsquo;s commitment to accountability in public procurement. Each unit was allocated to vetted beneficiaries drawn from the county&rsquo;s housing waitlist, following a transparent selection process overseen by the National Housing Corporation (NHC) and county housing officials.</p>\\r\\n\\r\\n              <div class=\\\"article-pullquote\\\" role=\\\"blockquote\\\">\\r\\n                <p>&ldquo;Today, Trans-Nzoia County delivers on its promise. These 200 families will no longer pay rent to landlords who do not care about their dignity. They now have title to a home &mdash; built with public funds, for the people of this county.&rdquo;</p>\\r\\n                <div class=\\\"article-pullquote-attr\\\">\\r\\n                  <i class=\\\"fa-solid fa-quote-left\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                  H.E. George Natembeya, Governor, Trans-Nzoia County &mdash; 15 May 2026\\r\\n                </div>\\r\\n              </div>\\r\\n\\r\\n              <p>The Maili Tatu Estate project, which forms the centrepiece of Kitale Central Constituency&rsquo;s AHP allocation, comprises a total of 600 units across three phases. Phases 2 and 3 &mdash; covering the remaining 400 units &mdash; are currently under active construction, with completion projected for Q1 2027. The project was awarded to Ramco Builders Ltd under a competitive tender process, and has been monitored through the county&rsquo;s integrated AHP project tracker.</p>\\r\\n\\r\\n              <!-- Stat Strip -->\\r\\n              <div class=\\\"article-stats-strip\\\" aria-label=\\\"Project key statistics\\\">\\r\\n                <div class=\\\"article-stat-card\\\">\\r\\n                  <span class=\\\"article-stat-num\\\">200</span>\\r\\n                  <span class=\\\"article-stat-lbl\\\">Units Delivered</span>\\r\\n                </div>\\r\\n                <div class=\\\"article-stat-card\\\">\\r\\n                  <span class=\\\"article-stat-num\\\">600</span>\\r\\n                  <span class=\\\"article-stat-lbl\\\">Total Planned</span>\\r\\n                </div>\\r\\n                <div class=\\\"article-stat-card\\\">\\r\\n                  <span class=\\\"article-stat-num\\\">3</span>\\r\\n                  <span class=\\\"article-stat-lbl\\\">Phases</span>\\r\\n                </div>\\r\\n              </div>\\r\\n\\r\\n              <!-- Callout Box -->\\r\\n              <div class=\\\"article-callout\\\" role=\\\"note\\\" aria-label=\\\"What this means for beneficiaries\\\">\\r\\n                <div class=\\\"article-callout-head\\\">\\r\\n                  <i class=\\\"fa-solid fa-lightbulb\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                  What This Means for Beneficiaries\\r\\n                </div>\\r\\n                <div class=\\\"article-callout-body\\\">\\r\\n                  <p>Beneficiaries who have been allocated units at Maili Tatu Estate are entitled to the following:</p>\\r\\n                  <ul>\\r\\n                    <li>A 30-year mortgage arrangement at a subsidised interest rate of 3% per annum through the Kenya Mortgage Refinance Company (KMRC).</li>\\r\\n                    <li>Full title deed registration processed by the Lands Ministry within 90 days of handover.</li>\\r\\n                    <li>Access to the National Construction Authority (NCA) defects liability coverage for 12 months post-handover.</li>\\r\\n                    <li>Management fee waiver for the first six months through the county estate management office.</li>\\r\\n                  </ul>\\r\\n                </div>\\r\\n              </div>\\r\\n\\r\\n              <h2>About the Maili Tatu Estate Project</h2>\\r\\n\\r\\n              <p>Situated on a 12-acre parcel of public land approximately 3 kilometres from Kitale town centre, the Maili Tatu Estate was designed by Nairobi-based architects Mungai &amp; Associates to deliver high-density, medium-rise residential units that maximise land use while providing adequate amenity space. Each block is four storeys high, with shared stairwells, ground-floor parking bays, and a communal courtyard at its centre.</p>\\r\\n\\r\\n              <!-- Inline Figure -->\\r\\n              <figure class=\\\"article-figure\\\">\\r\\n                <img src=\\\"uploads/news/maili-tatu-construction.jpg\\\"\\r\\n                     alt=\\\"Aerial view of Maili Tatu Estate construction progress showing completed Blocks Aâ€“E and ongoing works on Block F\\\"\\r\\n                     loading=\\\"lazy\\\"\\r\\n                     onerror=\\\"this.style.display=\'none\'\\\">\\r\\n                <figcaption>\\r\\n                  <i class=\\\"fa-solid fa-camera\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                  Aerial view of Maili Tatu Estate showing completed Blocks Aâ€“E (foreground) and ongoing Phase 2 construction. Photo: Trans-Nzoia County Government.\\r\\n                </figcaption>\\r\\n              </figure>\\r\\n\\r\\n              <p>Infrastructure provisions at the estate include piped water through a dedicated NAWASCO connection, an on-site sewage treatment plant, fibre-optic cabling ducted in all blocks, and a solar hybrid street-lighting system. A primary school site and a community health post have been earmarked within the estate master plan and are expected to be developed in partnership with the respective county departments in the 2026/27 financial year.</p>\\r\\n\\r\\n              <!-- Unit Breakdown Table -->\\r\\n              <div class=\\\"article-table-wrap\\\" role=\\\"region\\\" aria-label=\\\"Unit type breakdown for Phase 1\\\">\\r\\n                <table class=\\\"article-table\\\">\\r\\n                  <caption style=\\\"text-align:left;padding:.5rem 1.1rem;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--neutral-500);\\\">Phase 1 â€” Unit Type Breakdown</caption>\\r\\n                  <thead>\\r\\n                    <tr>\\r\\n                      <th scope=\\\"col\\\">Unit Type</th>\\r\\n                      <th scope=\\\"col\\\">Floor Area</th>\\r\\n                      <th scope=\\\"col\\\">No. of Units</th>\\r\\n                      <th scope=\\\"col\\\">Monthly Payment</th>\\r\\n                      <th scope=\\\"col\\\">Status</th>\\r\\n                    </tr>\\r\\n                  </thead>\\r\\n                  <tbody>\\r\\n                    <tr>\\r\\n                      <td>1-Bedroom</td>\\r\\n                      <td>36 m&sup2;</td>\\r\\n                      <td>120</td>\\r\\n                      <td>KSh 6,500</td>\\r\\n                      <td><span style=\\\"color:#16a34a;font-weight:700;\\\">&#10003; Delivered</span></td>\\r\\n                    </tr>\\r\\n                    <tr>\\r\\n                      <td>2-Bedroom</td>\\r\\n                      <td>55 m&sup2;</td>\\r\\n                      <td>72</td>\\r\\n                      <td>KSh 10,000</td>\\r\\n                      <td><span style=\\\"color:#16a34a;font-weight:700;\\\">&#10003; Delivered</span></td>\\r\\n                    </tr>\\r\\n                    <tr>\\r\\n                      <td>2-Bed (Accessible)</td>\\r\\n                      <td>58 m&sup2;</td>\\r\\n                      <td>8</td>\\r\\n                      <td>KSh 10,000</td>\\r\\n                      <td><span style=\\\"color:#16a34a;font-weight:700;\\\">&#10003; Delivered</span></td>\\r\\n                    </tr>\\r\\n                    <tr>\\r\\n                      <td><strong>Phase 1 Total</strong></td>\\r\\n                      <td>&mdash;</td>\\r\\n                      <td><strong>200</strong></td>\\r\\n                      <td>&mdash;</td>\\r\\n                      <td><strong>Completed</strong></td>\\r\\n                    </tr>\\r\\n                  </tbody>\\r\\n                </table>\\r\\n              </div>\\r\\n\\r\\n              <h2>Beneficiary Selection Process</h2>\\r\\n\\r\\n              <p>The selection of Phase 1 beneficiaries was conducted over a three-month period between February and April 2026, involving joint teams from the NHC, the Trans-Nzoia County Department of Land, Housing &amp; Physical Planning, and independent civil society observers. Applicants were ranked based on income verification, residency duration in Trans-Nzoia County, vulnerability status, and existing housing conditions. Priority was given to civil servants earning below KSh 30,000 per month, single-parent households, persons with disabilities, and informal sector workers registered with the Kenya Revenue Authority (KRA).</p>\\r\\n\\r\\n              <p>A total of 4,812 applications were received for the 200 Phase 1 units, representing an oversubscription ratio of approximately 24:1. Unsuccessful applicants have been placed on a county waitlist and will be given first consideration when Phase 2 and Phase 3 units become available. The county has committed to publishing the full beneficiary list on the AHP Tracker portal within 14 days of the handover ceremony in the interest of transparency and public accountability.</p>\\r\\n\\r\\n              <div class=\\\"article-pullquote\\\" role=\\\"blockquote\\\">\\r\\n                <p>&ldquo;The process was fair and I was surprised. I had applied three times before for other government schemes and never heard back. This time I got a text message and then a letter. The house is real and it is mine.&rdquo;</p>\\r\\n                <div class=\\\"article-pullquote-attr\\\">\\r\\n                  <i class=\\\"fa-solid fa-quote-left\\\" aria-hidden=\\\"true\\\"></i>\\r\\n                  Mary Wanjiku, beneficiary, Block C Unit 12, Maili Tatu Estate\\r\\n                </div>\\r\\n              </div>\\r\\n\\r\\n              <p>Cabinet Secretary Charles Hinga, speaking at the ceremony, commended Trans-Nzoia County for being among the first counties under the national AHP framework to achieve a Phase 1 handover, and called on other counties to replicate the model. He also announced that an additional KSh 450 million had been allocated to Trans-Nzoia County under the Supplementary Budget to accelerate Phase 2 construction at Maili Tatu and fund groundbreaking at two new sites in Endebess and Saboti constituencies.</p>\\r\\n\\r\\n            </article><!-- /article-prose -->\\r\\n\\r\\n            <!-- Tags -->\\r\\n            <div class=\\\"article-tags-wrap\\\" aria-label=\\\"Article tags\\\">\\r\\n              <span class=\\\"article-tags-label\\\"><i class=\\\"fa-solid fa-tag\\\" aria-hidden=\\\"true\\\"></i> Tags</span>\\r\\n              <a href=\\\"news.php?category=programme-updates\\\" class=\\\"article-tag\\\">Programme Updates</a>\\r\\n              <a href=\\\"news.php?category=community\\\" class=\\\"article-tag\\\">Community</a>\\r\\n              <a href=\\\"news.php?category=official\\\" class=\\\"article-tag\\\">Official</a>\\r\\n              <a href=\\\"news.php\\\" class=\\\"article-tag\\\">Maili Tatu Estate</a>\\r\\n              <a href=\\\"news.php\\\" class=\\\"article-tag\\\">Kitale</a>\\r\\n              <a href=\\\"news.php\\\" class=\\\"article-tag\\\">Housing Handover</a>\\r\\n            </div>\\r\\n\\r\\n            <!-- Author Block -->\\r\\n            <div class=\\\"article-author-block\\\" aria-label=\\\"Article author\\\">\\r\\n              <div class=\\\"article-author-icon\\\" aria-hidden=\\\"true\\\">\\r\\n                <i class=\\\"fa-solid fa-building-columns\\\"></i>\\r\\n              </div>\\r\\n              <div>\\r\\n                <div class=\\\"article-author-role\\\">Published by</div>\\r\\n                <div class=\\\"article-author-name\\\">Trans-Nzoia County Government</div>\\r\\n                <div class=\\\"article-author-desc\\\">Department of Land, Housing &amp; Physical Planning &mdash; County Headquarters, Kitale. This article is an official communication from the Trans-Nzoia County Government Affordable Housing Programme.</div>\\r\\n              </div>\\r\\n            </div>\\r\\n\\r\\n            <!-- Feedback Widget -->\\r\\n            <div class=\\\"article-feedback\\\" aria-label=\\\"Article feedback\\\">\\r\\n              <p class=\\\"article-feedback-q\\\">Was this article helpful?</p>\\r\\n              <div class=\\\"article-feedback-btns\\\">\\r\\n                <button class=\\\"article-feedback-btn is-yes\\\" type=\\\"button\\\" aria-label=\\\"Yes, this was helpful\\\">\\r\\n                  <i class=\\\"fa-solid fa-thumbs-up\\\" aria-hidden=\\\"true\\\"></i> Yes, helpful\\r\\n                </button>\\r\\n                <button class=\\\"article-feedback-btn is-no\\\" type=\\\"button\\\" aria-label=\\\"No, this was not helpful\\\">\\r\\n                  <i class=\\\"fa-solid fa-thumbs-down\\\" aria-hidden=\\\"true\\\"></i> Not helpful\\r\\n                </button>\\r\\n              </div>\\r\\n              <p class=\\\"article-feedback-thanks\\\" aria-live=\\\"polite\\\">\\r\\n                <i class=\\\"fa-solid fa-circle-check\\\" aria-hidden=\\\"true\\\"></i> Thank you for your feedback!\\r\\n              </p>\\r\\n            </div>\\r\\n\\r\\n            <!-- Actions -->\\r\\n            <div class=\\\"article-actions\\\" aria-label=\\\"Article actions\\\">\\r\\n              <button class=\\\"article-action-btn\\\" data-action=\\\"print\\\" type=\\\"button\\\">\\r\\n                <i class=\\\"fa-solid fa-print\\\" aria-hidden=\\\"true\\\"></i> Print Article\\r\\n              </button>\\r\\n              <button class=\\\"article-action-btn\\\" data-action=\\\"copy-link\\\" type=\\\"button\\\">\\r\\n                <i class=\\\"fa-solid fa-link\\\" aria-hidden=\\\"true\\\"></i> Copy