(56, 12, 'source_snapshot', 'Frontend Source Snapshot', 'source', 0, 'reference', 1, 0, '{\"source_file\":\"leadership.php\",\"meta\":{\"pageTitle\":\"Programme Leadership | Trans-Nzoia AHP Tracker\",\"pageDescription\":\"Programme leadership of the Trans-Nzoia Affordable Housing Programme â€” national government hierarchy, field office, contractors and implementing partners.\",\"pageKeywords\":\"Trans-Nzoia affordable housing leadership, Moses Owuor, AHP Kenya, State Department Housing, county director housing\",\"canonicalUrl\":\"https://housing.transnzoia.go.ke/leadership.php\",\"activePage\":\"leadership\"},\"headings\":[{\"level\":1,\"text\":\"The People Delivering Trans-Nzoia’s Housing Future\"},{\"level\":2,\"text\":\"From National Government to Your Doorstep\"},{\"level\":3,\"text\":\"H.E. Dr. William S. Ruto\"},{\"level\":3,\"text\":\"Hon. Alice Wahome\"},{\"level\":3,\"text\":\"Eng. Charles Hinga\"},{\"level\":3,\"text\":\"Affordable Housing Board\"},{\"level\":3,\"text\":\"County Directors (47 Counties)\"},{\"level\":3,\"text\":\"Moses Owuor\"},{\"level\":3,\"text\":\"Project Monitoring Officers\"},{\"level\":3,\"text\":\"Site Supervisors (8 Sites)\"},{\"level\":3,\"text\":\"Community Liaison Officers\"},{\"level\":2,\"text\":\"Senior Officials Driving the Programme\"},{\"level\":3,\"text\":\"H.E. Dr. William Samoei Ruto\"},{\"level\":3,\"text\":\"Hon. Alice Wahome\"},{\"level\":3,\"text\":\"Eng. Charles Hinga\"},{\"level\":3,\"text\":\"Affordable Housing Board\"},{\"level\":2,\"text\":\"Moses Owuor\"},{\"level\":4,\"text\":\"Key Responsibilities\"},{\"level\":2,\"text\":\"Building Trans-Nzoia’s Affordable Homes\"},{\"level\":3,\"text\":\"Apex Construct Ltd\"},{\"level\":3,\"text\":\"Nexus Builders Kenya\"},{\"level\":3,\"text\":\"BuildCore East Africa\"},{\"level\":3,\"text\":\"Landmark Structures Ltd\"},{\"level\":3,\"text\":\"Greenfield Construction Co.\"},{\"level\":3,\"text\":\"ProBuild Kenya Ltd\"},{\"level\":3,\"text\":\"Atlas Contractors Ltd\"},{\"level\":3,\"text\":\"Horizon Builders Ltd\"},{\"level\":2,\"text\":\"What Our Leaders & Builders Say\"},{\"level\":2,\"text\":\"The Organisations Behind the Programme\"},{\"level\":3,\"text\":\"State Dept. of Housing\"},{\"level\":3,\"text\":\"Affordable Housing Board\"},{\"level\":3,\"text\":\"NEMA\"},{\"level\":3,\"text\":\"NCA\"},{\"level\":3,\"text\":\"KMRC\"},{\"level\":3,\"text\":\"Boma Yangu / eCitizen\"},{\"level\":2,\"text\":\"Reach the Programme Leadership\"}],\"sections\":[{\"order\":1,\"id\":\"\",\"class\":\"ld-hero\",\"aria_label\":\"Programme leadership overview\",\"labelled_by\":\"\"},{\"order\":2,\"id\":\"\",\"class\":\"ld-org fade-up\",\"aria_label\":\"Programme chain of command\",\"labelled_by\":\"\"},{\"order\":3,\"id\":\"\",\"class\":\"ld-national fade-up\",\"aria_label\":\"National programme leadership\",\"labelled_by\":\"\"},{\"order\":4,\"id\":\"\",\"class\":\"ld-spotlight fade-up\",\"aria_label\":\"Trans-Nzoia county director spotlight\",\"labelled_by\":\"\"},{\"order\":5,\"id\":\"\",\"class\":\"ld-contractors fade-up\",\"aria_label\":\"Programme contractors\",\"labelled_by\":\"\"},{\"order\":6,\"id\":\"\",\"class\":\"ld-quotes fade-up\",\"aria_label\":\"In their own words â€” leadership quotes\",\"labelled_by\":\"\"},{\"order\":7,\"id\":\"\",\"class\":\"ld-partners fade-up\",\"aria_label\":\"Implementing partner organisations\",\"labelled_by\":\"\"},{\"order\":8,\"id\":\"\",\"class\":\"ld-cta fade-up\",\"aria_label\":\"Contact the field office\",\"labelled_by\":\"\"}],\"images\":[{\"src\":\"uploads/heroes/hero-main.jpg\",\"alt\":\"\",\"loading\":\"eager\"}],\"links\":[{\"href\":\"index.php\",\"text\":\"Home\"},{\"href\":\"about.php\",\"text\":\"About\"},{\"href\":\"contact.php\",\"text\":\"Contact the Field Office\"},{\"href\":\"https://www.ardhi.go.ke\",\"text\":\"\"},{\"href\":\"https://ahb.go.ke\",\"text\":\"\"},{\"href\":\"https://www.nema.go.ke\",\"text\":\"\"},{\"href\":\"https://www.nca.go.ke\",\"text\":\"\"},{\"href\":\"https://www.