INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(258, 66, 'legal_document', 'Privacy Policy | Trans-Nzoia AHP Tracker Document', 'document', 10, 'document', 1, 0, '{\"title\":\"Privacy Policy | Trans-Nzoia AHP Tracker\",\"body\":\"<section class=\\\"lg-section\\\" id=\\\"pp-intro\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">1</span> Introduction</h2>\\r\\n          <p>Trans-Nzoia County Government (\\\"<strong>we</strong>\\\", \\\"<strong>us</strong>\\\", \\\"<strong>the County</strong>\\\") is committed to protecting your personal data and respecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard information when you access the Trans-Nzoia Affordable Housing Programme (AHP) Tracker website and related digital services.</p>\\r\\n          <p>This policy applies to all information collected through our website at <strong>housing.transnzoia.go.ke</strong>, the AHP staff portal, online enquiry forms, and any other services we operate in connection with the county\'s affordable housing programme.</p>\\r\\n          <div class=\\\"lg-callout lg-callout--info\\\">\\r\\n            <i class=\\\"fa-solid fa-circle-info\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Kenya Data Protection Act 2019</strong>\\r\\n              <p>This policy is drafted in compliance with the Kenya Data Protection Act 2019, the Data Protection (General) Regulations 2021, and any applicable guidelines issued by the Office of the Data Protection Commissioner (ODPC Kenya).</p>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>By using our website or submitting information to us, you acknowledge that you have read and understood this Privacy Policy. If you do not agree with the terms of this policy, please discontinue use of our services.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-controller\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">2</span> Data Controller</h2>\\r\\n          <p>The data controller responsible for your personal information is:</p>\\r\\n          <div class=\\\"lg-data-card\\\">\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Entity</span><span class=\\\"lg-data-val\\\">Trans-Nzoia County Government</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Department</span><span class=\\\"lg-data-val\\\">Department of Land, Housing &amp; Physical Planning</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Address</span><span class=\\\"lg-data-val\\\">Ardhi House, County Commissioner\'s Premises, Kitale, Trans-Nzoia County, Kenya</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Phone</span><span class=\\\"lg-data-val\\\">+254 53 000 0000</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Email</span><span class=\\\"lg-data-val\\\">housing@transnzoia.go.ke</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">DPO Email</span><span class=\\\"lg-data-val\\\">dpo@transnzoia.go.ke</span></div>\\r\\n          </div>\\r\\n          <p>Our Data Protection Officer (DPO) oversees compliance with data protection law and is your first point of contact for any data privacy enquiries.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-collect\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">3</span> Data We Collect</h2>\\r\\n          <p>We collect different categories of information depending on how you interact with our services:</p>\\r\\n          <h3 class=\\\"lg-subsection-heading\\\">3.1 Information You Provide Directly</h3>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Identity data:</strong> full name, national ID number, date of birth, gender</li>\\r\\n            <li><strong>Contact data:</strong> postal address, telephone number, email address</li>\\r\\n            <li><strong>Housing application data:</strong> employment status, household income, household size, current housing status, constituency of residence, supporting documentation</li>\\r\\n            <li><strong>Enquiry data:</strong> the content of messages sent via our contact form, including any attachments you voluntarily submit</li>\\r\\n            <li><strong>Staff portal credentials:</strong> email address, hashed password, role/department assignment (for authorised county staff only)</li>\\r\\n          </ul>\\r\\n          <h3 class=\\\"lg-subsection-heading\\\">3.2 Information Collected Automatically</h3>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Technical data:</strong> IP address, browser type and version, operating system, device type, screen resolution</li>\\r\\n            <li><strong>Usage data:</strong> pages visited, links clicked, time spent on pages, referring URL</li>\\r\\n            <li><strong>Session data:</strong> session cookies required for authenticated portal access (see Section 9)</li>\\r\\n          </ul>\\r\\n          <div class=\\\"lg-callout lg-callout--warn\\\">\\r\\n            <i class=\\\"fa-solid fa-triangle-exclamation\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>We do not collect sensitive personal data</strong>\\r\\n              <p>We do not intentionally collect special category data (ethnicity, health, biometrics, religious beliefs) except where required by the national government\'s beneficiary verification process under the State Department for Housing regulations.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-use\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">4</span> How We Use Your Data</h2>\\r\\n          <p>We use the personal data we collect for the following purposes:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Programme administration:</strong> processing housing applications, verifying eligibility, conducting beneficiary balloting, communicating allocation decisions</li>\\r\\n            <li><strong>Communication:</strong> responding to enquiries, sending programme updates, issuing official notices regarding your application status</li>\\r\\n            <li><strong>Compliance &amp; legal obligations:</strong> fulfilling reporting requirements to the National Treasury, State Department for Housing, and the Affordable Housing Board (AHB)</li>\\r\\n            <li><strong>Website operation:</strong> maintaining and improving this website, troubleshooting technical issues, preventing fraud and abuse</li>\\r\\n            <li><strong>Analytics:</strong> understanding how the public uses our services so we can improve the user experience â€” we use anonymised, aggregated data only for this purpose</li>\\r\\n            <li><strong>Staff portal management:</strong> managing access rights, audit logs, and security of authenticated county staff accounts</li>\\r\\n          </ul>\\r\\n          <p>We will not use your personal data for commercial marketing, sell your data to third parties, or use it for any purpose incompatible with the original reason for collection.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-legal-basis\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">5</span> Legal Basis for Processing</h2>\\r\\n          <p>Under the Kenya Data Protection Act 2019, we must have a lawful basis for processing your personal data. Our processing activities rely on one or more of the following bases:</p>\\r\\n          <div class=\\\"lg-basis-grid\\\">\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-handshake\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Consent</strong><p>For newsletter subscriptions and optional enquiry form submissions.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-file-signature\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Contractual necessity</strong><p>Where processing is necessary to perform our obligations to a housing applicant.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-scale-balanced\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Legal obligation</strong><p>Where we are required to process data by the Housing Act (Cap. 117), County Governments Act 2012, or other Kenyan legislation.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-building-flag\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Public task</strong><p>For processing in the exercise of official county government authority vested in us under the Constitution of Kenya.</p></div>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-sharing\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">6</span> Data Sharing &amp; Third Parties</h2>\\r\\n          <p>We may share your personal data with the following parties where necessary and lawful:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Affordable Housing Board (AHB):</strong> the national body responsible for programme oversight receives applicant data to verify eligibility and register allocations</li>\\r\\n            <li><strong>State Department for Housing &amp; Urban Development:</strong> national-level reporting as mandated by the Affordable Housing Act</li>\\r\\n            <li><strong>National Housing Corporation (NHC):</strong> where applicable for financing and unit allocation verification</li>\\r\\n            <li><strong>Other Trans-Nzoia County departments:</strong> internal sharing limited to the County Revenue Authority (rate verification) and County Planning department</li>\\r\\n            <li><strong>eCitizen / Kenya National BRS:</strong> identity verification against national databases via the IPRS</li>\\r\\n            <li><strong>Technical service providers:</strong> web hosting, email services, and IT support providers are bound by strict data processing agreements and may not use your data for their own purposes</li>\\r\\n          </ul>\\r\\n          <div class=\\\"lg-callout lg-callout--success\\\">\\r\\n            <i class=\\\"fa-solid fa-circle-check\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>No commercial data sales</strong>\\r\\n              <p>We do not sell, rent, lease, or share your personal data with any commercial entity for marketing or profiling purposes. Your information is used solely for the administration of the Affordable Housing Programme.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-retention\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">7</span> Data Retention</h2>\\r\\n          <p>We retain personal data only for as long as necessary to fulfil the purpose for which it was collected, and as required by Kenyan law:</p>\\r\\n          <div class=\\\"lg-retention-table\\\">\\r\\n            <div class=\\\"lg-rt-head\\\">\\r\\n              <span>Data Category</span><span>Retention Period</span><span>Reason</span>\\r\\n            </div>\\r\\n            <div class=\\\"lg-rt-row\\\">\\r\\n              <span>Housing application records</span><span>7 years after programme close</span><span>Public audit &amp; accountability requirements</span>\\r\\n            </div>\\r\\n            <div class=\\\"lg-rt-row\\\">\\r\\n              <span>Beneficiary allocation records</span><span>Permanent (archived)</span><span>Constitutional accountability for public resources</span>\\r\\n            </div>\\r\\n            <div class=\\\"lg-rt-row\\\">\\r\\n              <span>Online enquiry data</span><span>2 years</span><span>Follow-up and dispute resolution</span>\\r\\n            </div>\\r\\n            <div class=\\\"lg-rt-row\\\">\\r\\n              <span>Staff portal credentials</span><span>Duration of employment + 1 year</span><span>Security and audit logs</span>\\r\\n            </div>\\r\\n            <div class=\\\"lg-rt-row\\\">\\r\\n              <span>Web server access logs</span><span>90 days</span><span>Security monitoring</span>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>After the retention period expires, data is securely deleted or anonymised in accordance with our Records Management Policy.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-rights\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">8</span> Your Rights</h2>\\r\\n          <p>Under the Kenya Data Protection Act 2019, you have the following rights in relation to your personal data:</p>\\r\\n          <div class=\\\"lg-rights-grid\\\">\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-eye\\\" aria-hidden=\\\"true\\\"></i><div><strong>Right of Access</strong><p>Request a copy of the personal data we hold about you.</p></div></div>\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-pen-to-square\\\" aria-hidden=\\\"true\\\"></i><div><strong>Right to Rectification</strong><p>Request correction of inaccurate or incomplete data.</p></div></div>\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-trash-can\\\" aria-hidden=\\\"true\\\"></i><div><strong>Right to Erasure</strong><p>Request deletion of your data where there is no compelling reason for continued processing.</p></div></div>\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-right-left\\\" aria-hidden=\\\"true\\\"></i><div><strong>Right to Portability</strong><p>Receive your data in a structured, commonly used format.</p></div></div>\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-hand\\\" aria-hidden=\\\"true\\\"></i><div><strong>Right to Object</strong><p>Object to processing based on legitimate interests or public task.</p></div></div>\\r\\n            <div class=\\\"lg-right-item\\\"><i class=\\\"fa-solid fa-rotate-left\\\" aria-hidden=\\\"true\\\"></i><div><strong>Withdraw Consent</strong><p>Where processing is based on consent, withdraw it at any time without affecting prior processing.</p></div></div>\\r\\n          </div>\\r\\n          <p>To exercise any of these rights, submit a written request to <strong>dpo@transnzoia.go.ke</strong>. We will respond within 21 days as required by law. We may need to verify your identity before fulfilling the request.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-cookies\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">9</span> Cookies &amp; Tracking</h2>\\r\\n          <p>We use a minimal set of cookies strictly necessary for the operation of this website. We do not use advertising or tracking cookies, and we do not permit third-party trackers on this site.</p>\\r\\n          <div class=\\\"lg-retention-table\\\">\\r\\n            <div class=\\\"lg-rt-head\\\"><span>Cookie Name</span><span>Type</span><span>Purpose</span><span>Duration</span></div>\\r\\n            <div class=\\\"lg-rt-row\\\"><span><code>ahp_session</code></span><span>Session</span><span>Staff portal authentication</span><span>Session (deleted on close)</span></div>\\r\\n            <div class=\\\"lg-rt-row\\\"><span><code>ahp_remember</code></span><span>Persistent</span><span>\\\"Remember me\\\" login convenience</span><span>30 days</span></div>\\r\\n            <div class=\\\"lg-rt-row\\\"><span><code>ahp_csrf</code></span><span>Session</span><span>Cross-site request forgery protection</span><span>Session</span></div>\\r\\n          </div>\\r\\n          <p>Our public-facing pages (tracker, projects, news) operate without any cookies. No analytics pixels, social media embeds, or advertising networks are loaded on this website.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-security\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">10</span> Security Measures</h2>\\r\\n          <p>We take the security of your personal data seriously and implement appropriate technical and organisational measures to protect it against unauthorised access, loss, destruction, or disclosure. These include:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>HTTPS encryption for all data in transit</li>\\r\\n            <li>Encrypted storage for all sensitive data fields at rest</li>\\r\\n            <li>Role-based access controls â€” staff can only access data relevant to their duties</li>\\r\\n            <li>Regular security audits and vulnerability assessments of our web infrastructure</li>\\r\\n            <li>Mandatory data protection training for all county staff with access to personal data</li>\\r\\n            <li>Incident response procedures â€” in the event of a breach, we will notify the ODPC within 72 hours and affected individuals as required by law</li>\\r\\n          </ul>\\r\\n          <p>While we take every reasonable precaution, no internet transmission or electronic storage method is 100% secure. We cannot guarantee absolute security but are committed to protecting your data to the highest practical standard.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-children\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">11</span> Children\'s Privacy</h2>\\r\\n          <p>Our website and the AHP staff portal are intended for adults aged 18 and above. We do not knowingly collect personal data from children under 18 years of age. Housing applications require the applicant to be an adult Kenyan citizen.</p>\\r\\n          <p>If you believe a child has submitted personal data to us without parental consent, please contact our DPO at <strong>dpo@transnzoia.go.ke</strong> and we will promptly delete the information.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-changes\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">12</span> Changes to This Policy</h2>\\r\\n          <p>We may update this Privacy Policy from time to time to reflect changes in law, technology, or our data processing practices. When we make material changes, we will:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Update the \\\"Last updated\\\" date at the top of this page</li>\\r\\n            <li>Post a notice on our website homepage for at least 14 days</li>\\r\\n            <li>Where feasible, notify registered applicants by email</li>\\r\\n          </ul>\\r\\n          <p>We encourage you to review this page periodically. Continued use of our services after changes take effect constitutes acceptance of the updated policy.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"pp-contact\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">13</span> Contact &amp; Complaints</h2>\\r\\n          <p>If you have questions, concerns, or wish to exercise your data rights, please contact our Data Protection Officer:</p>\\r\\n          <div class=\\\"lg-data-card\\\">\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">DPO Name</span><span class=\\\"lg-data-val\\\">Data Protection Officer</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Email</span><span class=\\\"lg-data-val\\\">dpo@transnzoia.go.ke</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Post</span><span class=\\\"lg-data-val\\\">DPO, Trans-Nzoia County Government, P.O. Box 4210-30200, Kitale</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Phone</span><span class=\\\"lg-data-val\\\">+254 53 000 0000 Ext. 201</span></div>\\r\\n          </div>\\r\\n          <p>If you are not satisfied with our response, you have the right to lodge a complaint with the Office of the Data Protection Commissioner (ODPC Kenya):</p>\\r\\n          <div class=\\\"lg-data-card\\\">\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Website</span><span class=\\\"lg-data-val\\\"><a href=\\\"https://www.odpc.go.ke\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">www.odpc.go.ke</a></span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Email</span><span class=\\\"lg-data-val\\\">info@odpc.go.ke</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Address</span><span class=\\\"lg-data-val\\\">Westlands Commercial Centre, 9th Floor, Ring Road Westlands, Nairobi</span></div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <!-- Document footer -->\\r\\n        <div class=\\\"lg-doc-footer\\\">\\r\\n          <p>This policy was last reviewed and approved by the Trans-Nzoia County Government Legal Services Unit on <strong>1 January 2026</strong>. Document reference: <code>TNZ-PRIVACY-2026-01</code>.</p>\\r\\n          <div class=\\\"lg-doc-nav\\\">\\r\\n            <a href=\\\"terms.php\\\" class=\\\"lg-doc-nav-link\\\">\\r\\n              <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Terms of Use\\r\\n            </a>\\r\\n            <a href=\\\"disclaimer.php\\\" class=\\\"lg-doc-nav-link\\\">\\r\\n              <i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Disclaimer\\r\\n            </a>\\r\\n          </div>\\r\\n        </div>\"}', NULL, '2026-05-27 13:31:48'),
(260, 67, 'legal_document', 'Terms of Use | Trans-Nzoia AHP Tracker Document', 'document', 10, 'document', 1, 0, '{\"title\":\"Terms of Use | Trans-Nzoia AHP Tracker\",\"body\":\"<section class=\\\"lg-section\\\" id=\\\"tu-acceptance\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">1</span> Acceptance of Terms</h2>\\r\\n          <p>Welcome to the Trans-Nzoia County Affordable Housing Programme (AHP) Tracker. By accessing or using this website at <strong>housing.transnzoia.go.ke</strong>, you agree to be bound by these Terms of Use (&ldquo;Terms&rdquo;), our <a href=\\\"privacy.php\\\">Privacy Policy</a>, and our <a href=\\\"disclaimer.php\\\">Disclaimer</a>. These Terms form a legally binding agreement between you and Trans-Nzoia County Government.</p>\\r\\n          <p>If you do not agree with any part of these Terms, you must discontinue use of this website immediately. Continued use of the website after any modification constitutes your acceptance of the updated Terms.</p>\\r\\n          <div class=\\\"lg-callout lg-callout--info\\\">\\r\\n            <i class=\\\"fa-solid fa-circle-info\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Public Information Service</strong>\\r\\n              <p>This website is a public accountability and transparency tool operated by Trans-Nzoia County Government. Most content is freely accessible without registration. The Staff Portal is restricted to authorised county government personnel only.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-purpose\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">2</span> Website Purpose &amp; Scope</h2>\\r\\n          <p>The Trans-Nzoia AHP Tracker is an official public-facing website operated by the Department of Land, Housing &amp; Physical Planning. Its core purposes are:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Provide real-time and regularly updated information on affordable housing construction progress across all five constituencies of Trans-Nzoia County</li>\\r\\n            <li>Publish official notices, tender announcements, and programme milestones under the national Affordable Housing Programme (AHP)</li>\\r\\n            <li>Facilitate public accountability by making construction data, unit delivery timelines, and contractor performance information publicly accessible</li>\\r\\n            <li>Direct residents to the national Boma Yangu / eCitizen portal for housing applications and allocation decisions</li>\\r\\n            <li>Provide a restricted Staff Portal for authorised county officials to manage project data, field reports, and communications</li>\\r\\n          </ul>\\r\\n          <div class=\\\"lg-callout lg-callout--warn\\\">\\r\\n            <i class=\\\"fa-solid fa-triangle-exclamation\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Applications via eCitizen Only</strong>\\r\\n              <p>This website does not process housing applications directly. All formal applications must be submitted through the national <a href=\\\"https://ecitizen.go.ke\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">eCitizen / Boma Yangu</a> platform operated by the State Department for Housing &amp; Urban Development.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-acceptable\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">3</span> Acceptable Use</h2>\\r\\n          <p>You may use this website for lawful purposes only. When using this website, you agree <strong>not</strong> to:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Deploy any automated tool, script, spider, or scraper to extract data in a manner that places excessive load on our servers or circumvents access controls</li>\\r\\n            <li>Attempt to gain unauthorised access to the Staff Portal, administrative systems, databases, or any restricted section of this website</li>\\r\\n            <li>Transmit malware, viruses, ransomware, or any malicious code intended to disrupt, damage, or gain control of any computer system</li>\\r\\n            <li>Impersonate any county official, staff member, contractor, or other person in connection with this website</li>\\r\\n            <li>Use this website to spread misinformation, make false statements about the programme, or misrepresent published data</li>\\r\\n            <li>Reproduce, republish, or redistribute content from this website for commercial gain without prior written consent from Trans-Nzoia County Government</li>\\r\\n            <li>Conduct any activity that violates applicable Kenyan law, including the Computer Misuse and Cybercrimes Act 2018</li>\\r\\n          </ul>\\r\\n          <p>We reserve the right to block access to any person or entity found to be in violation of these standards, without prior notice.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-ip\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">4</span> Intellectual Property</h2>\\r\\n          <p>Unless otherwise stated, all content on this website &mdash; including text, graphics, maps, photographs, logos, icons, project data, and page layouts &mdash; is the property of Trans-Nzoia County Government or its licensed content providers.</p>\\r\\n          <h3 class=\\\"lg-subsection-heading\\\">4.1 Permitted Use</h3>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Access and read content for personal, non-commercial, and public information purposes</li>\\r\\n            <li>Print or save a single copy of individual pages for personal reference or official correspondence</li>\\r\\n            <li>Journalists may quote limited extracts for reporting purposes with clear attribution to Trans-Nzoia County Government</li>\\r\\n            <li>Academic and research use of aggregated data is permitted with proper citation of the Trans-Nzoia AHP Tracker as the source</li>\\r\\n          </ul>\\r\\n          <h3 class=\\\"lg-subsection-heading\\\">4.2 Prohibited Use</h3>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Commercial republication or redistribution of any content without written consent</li>\\r\\n            <li>Removal or alteration of any copyright, trademark, or attribution notices</li>\\r\\n            <li>Use of county government logos, seals, or official marks in a misleading context</li>\\r\\n            <li>Creation of derivative works or commercial databases from website content without authorisation</li>\\r\\n          </ul>\\r\\n          <p>Content reuse and licensing requests should be directed to <strong>housing@transnzoia.go.ke</strong>.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-portal\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">5</span> Staff Portal &amp; User Accounts</h2>\\r\\n          <p>Access to the AHP Staff Portal is restricted to authorised Trans-Nzoia County Government employees and designated contractors. Accounts are granted at the sole discretion of the County Director of Housing.</p>\\r\\n          <div class=\\\"lg-basis-grid\\\">\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-user-shield\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Account Security</strong><p>You are responsible for maintaining confidentiality of your credentials. Do not share passwords or permit unauthorised use of your account.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-triangle-exclamation\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Report Breaches</strong><p>Immediately report any suspected unauthorised access to your ICT administrator or to <strong>ict@transnzoia.go.ke</strong>.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-ban\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Account Termination</strong><p>Accounts may be suspended or revoked upon cessation of employment, contract end, or breach of these Terms.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-scroll\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Audit Logging</strong><p>All Staff Portal actions are logged and retained for security auditing. Logs may be used in disciplinary or legal proceedings.</p></div>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>Unauthorised access attempts are a criminal offence under the Computer Misuse and Cybercrimes Act 2018 and will be reported to relevant law enforcement authorities.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-accuracy\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">6</span> Information Accuracy &amp; Updates</h2>\\r\\n          <p>Trans-Nzoia County Government makes every reasonable effort to ensure information on this website is accurate, current, and complete. However, construction data, progress percentages, unit counts, and delivery timelines are subject to continuous revision as projects evolve.</p>\\r\\n          <div class=\\\"lg-callout lg-callout--info\\\">\\r\\n            <i class=\\\"fa-solid fa-circle-info\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Data Currency Notice</strong>\\r\\n              <p>Project data is updated on a best-efforts basis by county field officers. There may be a lag between on-site events and their reflection on this tracker. Official certified progress records are maintained by the respective Clerks of Works and county project managers.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>If you notice a factual error or data discrepancy, please report it to <strong>housing@transnzoia.go.ke</strong> so we can investigate and correct it promptly.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-third-party\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">7</span> Third-Party Links &amp; Services</h2>\\r\\n          <p>This website contains links to third-party websites and services for reference and convenience, including:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>eCitizen / Boma Yangu</strong> &mdash; the national housing application portal operated by the State Department for Housing</li>\\r\\n            <li><strong>Kenya National Bureau of Statistics (KNBS)</strong> &mdash; for socioeconomic data references</li>\\r\\n            <li><strong>National Environment Management Authority (NEMA)</strong> &mdash; for environmental clearance references</li>\\r\\n            <li><strong>National Housing Corporation (NHC)</strong> &mdash; for financing programme information</li>\\r\\n            <li><strong>Affordable Housing Board (AHB)</strong> &mdash; for national programme oversight updates</li>\\r\\n          </ul>\\r\\n          <p>Trans-Nzoia County Government has no control over the content, privacy practices, or availability of third-party websites and is not responsible for any loss or damage arising from your use of them. Inclusion of a link does not constitute endorsement of that website or its content.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-warranties\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">8</span> Disclaimer of Warranties</h2>\\r\\n          <p>This website and its content are provided on an &ldquo;<strong>as is</strong>&rdquo; and &ldquo;<strong>as available</strong>&rdquo; basis, without warranties of any kind &mdash; either express or implied &mdash; to the fullest extent permissible under Kenyan law. Trans-Nzoia County Government does not warrant that:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>The website will be available, uninterrupted, or error-free at all times</li>\\r\\n            <li>Any defects or errors will be corrected immediately upon discovery</li>\\r\\n            <li>The website or its servers are free of viruses or other harmful components</li>\\r\\n            <li>Information on this website is complete, accurate, or up to date at every moment</li>\\r\\n          </ul>\\r\\n          <p>Please refer to our separate <a href=\\\"disclaimer.php\\\">Disclaimer</a> for a detailed statement on the limitations of data published on this website.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-liability\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">9</span> Limitation of Liability</h2>\\r\\n          <p>To the maximum extent permitted by law, Trans-Nzoia County Government, its officers, employees, and agents shall not be liable for any direct, indirect, incidental, consequential, special, or punitive damages arising from:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Your use of, or inability to use, this website or its content</li>\\r\\n            <li>Any reliance placed on information published on this website</li>\\r\\n            <li>Unauthorised access to or alteration of your data transmissions</li>\\r\\n            <li>Any interruption, suspension, or cessation of this website or its services</li>\\r\\n            <li>Any loss of profits, data, business opportunity, or goodwill</li>\\r\\n          </ul>\\r\\n          <p>Nothing in these Terms shall exclude or limit liability for death or personal injury caused by negligence, or for any fraudulent misrepresentation, or any other liability that cannot be excluded under Kenyan law.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-privacy\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">10</span> Privacy</h2>\\r\\n          <p>Your use of this website is also governed by our <a href=\\\"privacy.php\\\">Privacy Policy</a>, which is incorporated into these Terms by reference. The Privacy Policy explains how we collect, use, and protect personal data you provide or that is automatically collected during your visit.</p>\\r\\n          <p>By using this website, you consent to data processing as described in the Privacy Policy. If you do not agree with how we handle personal data, please discontinue use of this website.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-governing\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">11</span> Governing Law &amp; Jurisdiction</h2>\\r\\n          <p>These Terms shall be governed by and construed in accordance with the laws of the Republic of Kenya, including:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>The Constitution of Kenya 2010</li>\\r\\n            <li>The County Governments Act 2012</li>\\r\\n            <li>The Computer Misuse and Cybercrimes Act 2018</li>\\r\\n            <li>The Kenya Information and Communications Act (Cap. 411A)</li>\\r\\n            <li>The Affordable Housing Act 2024</li>\\r\\n          </ul>\\r\\n          <p>Any dispute arising from these Terms shall be subject to the exclusive jurisdiction of the courts of Kenya. Disputes will first be referred for mediation through the Trans-Nzoia County Dispute Resolution Committee before proceeding to formal litigation.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-changes\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">12</span> Changes to These Terms</h2>\\r\\n          <p>We reserve the right to amend these Terms at any time to reflect changes in law, operational requirements, or website functionality. When we make material changes, we will:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Update the &ldquo;Last updated&rdquo; date at the top of this page</li>\\r\\n            <li>Post a notice on our website homepage for at least 14 days following the change</li>\\r\\n            <li>Where feasible, notify registered Staff Portal users by email</li>\\r\\n          </ul>\\r\\n          <p>Continued use of this website after changes take effect constitutes your acceptance of the revised Terms.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"tu-contact\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">13</span> Contact</h2>\\r\\n          <p>For questions about these Terms, to report a violation, or to request content use permission, please contact us:</p>\\r\\n          <div class=\\\"lg-data-card\\\">\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Entity</span><span class=\\\"lg-data-val\\\">Trans-Nzoia County Government</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Department</span><span class=\\\"lg-data-val\\\">Department of Land, Housing &amp; Physical Planning</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Address</span><span class=\\\"lg-data-val\\\">County Headquarters, Kitale, Trans-Nzoia County, Kenya</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Phone</span><span class=\\\"lg-data-val\\\">+254 53 000 0000</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Email</span><span class=\\\"lg-data-val\\\">housing@transnzoia.go.ke</span></div>\\r\\n          </div>\\r\\n          <p>For formal legal notices, address correspondence to the County Secretary, Trans-Nzoia County Government, P.O. Box 4210-30200, Kitale, Kenya.</p>\\r\\n        </section>\\r\\n\\r\\n        <div class=\\\"lg-doc-footer\\\">\\r\\n          <p>These Terms were last reviewed and approved by the Trans-Nzoia County Government Legal Services Unit on <strong>1 January 2026</strong>. Document reference: <code>TNZ-TERMS-2026-01</code>.</p>\\r\\n          <div class=\\\"lg-doc-nav\\\">\\r\\n            <a href=\\\"privacy.php\\\" class=\\\"lg-doc-nav-link\\\"><i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Privacy Policy</a>\\r\\n            <a href=\\\"disclaimer.php\\\" class=\\\"lg-doc-nav-link\\\"><i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Disclaimer</a>\\r\\n          </div>\\r\\n        </div>\"}', NULL, '2026-05-27 13:31:48');
INSERT INTO `cms_sections` (`id`, `page_id`, `section_key`, `label`, `section_type`, `sort_order`, `editor_mode`, `is_visible`, `is_locked`, `content_json`, `updated_by`, `updated_at`) VALUES
(262, 15, 'legal_document', 'Disclaimer | Trans-Nzoia AHP Tracker Document', 'document', 10, 'document', 1, 0, '{\"title\":\"Disclaimer | Trans-Nzoia AHP Tracker\",\"body\":\"<section class=\\\"lg-section\\\" id=\\\"ds-general\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">1</span> General Notice</h2>\\r\\n          <p>The Trans-Nzoia County Affordable Housing Programme (AHP) Tracker is an official public information website operated by Trans-Nzoia County Government. It is designed to promote transparency and public accountability in the delivery of the national Affordable Housing Programme within Trans-Nzoia County.</p>\\r\\n          <p>While every effort is made to ensure accuracy, this website is provided for <strong>general information and transparency purposes only</strong>. The information contained herein does not constitute official government correspondence, legal certification, or binding administrative decision unless explicitly stated as such with appropriate authorisation.</p>\\r\\n          <div class=\\\"lg-callout lg-callout--warn\\\">\\r\\n            <i class=\\\"fa-solid fa-triangle-exclamation\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Not Legally Binding</strong>\\r\\n              <p>Data published on this tracker does not constitute official government records, legal titles, approved development plans, or binding contractual obligations. All official records are maintained and certified by the relevant county and national government registries.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-project-data\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">2</span> Project Data &amp; Construction Progress</h2>\\r\\n          <p>Construction progress figures, unit counts, timeline estimates, contractor performance ratings, and completion percentages published on this website are based on field reports submitted by county-assigned Clerks of Works, project managers, and contractor submissions. These figures are subject to the following limitations:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Lag time:</strong> There may be a delay of up to 14 working days between on-site events and their publication on this tracker. Data displayed represents the most recent verified submission, not necessarily the real-time site status.</li>\\r\\n            <li><strong>Measurement standards:</strong> Progress percentages are assessed against the approved Bills of Quantities (BOQs) and programme milestones. Minor variations in methodology between different site officers may affect comparative figures.</li>\\r\\n            <li><strong>Force majeure:</strong> Timelines may be revised due to adverse weather, supply chain disruptions, labour disputes, contractor insolvency, design revisions, or other factors outside county government control.</li>\\r\\n            <li><strong>Provisional figures:</strong> Unit counts and allocation figures are based on current approved designs. Changes to approved architectural plans may alter final delivery numbers.</li>\\r\\n          </ul>\\r\\n          <p>For certified, legally valid progress records, contact the Department of Land, Housing &amp; Physical Planning directly.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-financial\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">3</span> Financial Information</h2>\\r\\n          <p>Budget figures, contract values, levy contribution rates, and financing information published on this website are provided for public transparency purposes. The following qualifications apply:</p>\\r\\n          <div class=\\\"lg-basis-grid\\\">\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-coins\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Contract Values</strong><p>Published contract values represent the original tender award amount. Variations, extensions, and supplementary agreements may alter final expenditure figures.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-percent\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Levy Rates</strong><p>Affordable Housing Levy contribution rates are determined by national legislation. This website may not reflect the most recent statutory amendments. Always verify with the Kenya Revenue Authority (KRA).</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-building-columns\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Mortgage Terms</strong><p>Illustrative mortgage and rent-to-own repayment figures are indicative only. Actual terms are determined by approved lending institutions and the Affordable Housing Board.</p></div>\\r\\n            </div>\\r\\n            <div class=\\\"lg-basis-item\\\">\\r\\n              <div class=\\\"lg-basis-icon\\\"><i class=\\\"fa-solid fa-chart-line\\\" aria-hidden=\\\"true\\\"></i></div>\\r\\n              <div><strong>Market Data</strong><p>Any property valuation or market comparison data is informational only and does not constitute a formal valuation or investment advice.</p></div>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>Official financial data is published by the Controller of Budget, the Auditor General, and the County Treasury in accordance with the Public Finance Management Act 2012.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-allocation\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">4</span> Allocation &amp; Eligibility Information</h2>\\r\\n          <p>Information about housing unit allocation, eligibility criteria, application processes, and balloting procedures published on this website is provided for general guidance only.</p>\\r\\n          <div class=\\\"lg-callout lg-callout--warn\\\">\\r\\n            <i class=\\\"fa-solid fa-triangle-exclamation\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Official Process via eCitizen / Boma Yangu</strong>\\r\\n              <p>All housing applications, eligibility determinations, and allocation decisions are administered exclusively through the national <a href=\\\"https://ecitizen.go.ke\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">eCitizen / Boma Yangu</a> platform under the Affordable Housing Board (AHB). Trans-Nzoia County Government does not make or influence individual allocation decisions.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n          <p>In the event of any conflict or discrepancy between information on this website and official communications from the Affordable Housing Board, the Affordable Housing Board&rsquo;s official communication shall prevail.</p>\\r\\n          <p>Any third party claiming to facilitate housing allocation in exchange for payment or favour is not acting on behalf of Trans-Nzoia County Government. Report such incidents to <strong>housing@transnzoia.go.ke</strong> or the Ethics and Anti-Corruption Commission (EACC).</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-maps\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">5</span> Maps &amp; Spatial Data</h2>\\r\\n          <p>Maps, site boundaries, constituency outlines, and spatial data displayed on this website are for illustrative and navigational purposes only. They are subject to the following limitations:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Administrative boundaries shown are based on the best available data at the time of publication and may not reflect current boundary determinations by the Independent Electoral and Boundaries Commission (IEBC)</li>\\r\\n            <li>Site location pins are approximate. Exact surveyed coordinates and legal plot boundaries are recorded in official title documents at the Survey of Kenya and county lands registry</li>\\r\\n            <li>Maps sourced from or rendered by third-party providers (e.g. Google Maps, OpenStreetMap) are subject to those providers&rsquo; own accuracy limitations and terms of use</li>\\r\\n            <li>No warranty is given that any map or spatial data accurately represents legal ownership, zoning classification, or planning approval status</li>\\r\\n          </ul>\\r\\n          <p>For surveyed plans, official site boundaries, or title information, contact the Department of Land, Housing &amp; Physical Planning or the Survey of Kenya.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-third-party\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">6</span> Third-Party Content &amp; External Links</h2>\\r\\n          <p>This website may reference, cite, or link to content from third-party organisations including national government agencies, development partners, contractors, and media sources. Trans-Nzoia County Government:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Does not endorse or verify the accuracy of third-party content referenced or linked from this website</li>\\r\\n            <li>Is not responsible for the availability, content, privacy practices, or security of any linked external website</li>\\r\\n            <li>Does not control third-party data sources and cannot guarantee their currency or completeness</li>\\r\\n            <li>May cite reports, studies, or statistics from third parties which represent the views of those organisations, not Trans-Nzoia County Government</li>\\r\\n          </ul>\\r\\n          <p>Any opinions, findings, or conclusions expressed in third-party materials cited on this website are those of the original authors.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-advice\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">7</span> No Professional Advice</h2>\\r\\n          <p>Nothing on this website constitutes or should be relied upon as:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li><strong>Legal advice</strong> &mdash; for legal matters relating to land tenure, housing rights, or contracts, consult a qualified advocate registered with the Law Society of Kenya</li>\\r\\n            <li><strong>Financial advice</strong> &mdash; for mortgage, investment, or financial planning decisions, consult a qualified financial adviser regulated by the Capital Markets Authority or Central Bank of Kenya</li>\\r\\n            <li><strong>Valuation advice</strong> &mdash; for property valuations, engage a registered valuer with the Institution of Surveyors of Kenya (ISK)</li>\\r\\n            <li><strong>Planning or engineering advice</strong> &mdash; for technical matters relating to construction or land use, engage registered professionals with the Engineers Board of Kenya (EBK) or Architectural Association of Kenya (AAK)</li>\\r\\n          </ul>\\r\\n          <div class=\\\"lg-callout lg-callout--info\\\">\\r\\n            <i class=\\\"fa-solid fa-circle-info\\\" aria-hidden=\\\"true\\\"></i>\\r\\n            <div>\\r\\n              <strong>Seek Professional Guidance</strong>\\r\\n              <p>Before making any significant decision based on information found on this website &mdash; including applying for housing, entering into contracts, or making financial commitments &mdash; we strongly recommend seeking independent professional advice appropriate to your circumstances.</p>\\r\\n            </div>\\r\\n          </div>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-availability\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">8</span> System Availability &amp; Technical Limitations</h2>\\r\\n          <p>This website is operated on a best-efforts basis. Trans-Nzoia County Government does not guarantee continuous, uninterrupted, or error-free availability of the website or its data services. Interruptions may occur due to:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Scheduled maintenance and system upgrades</li>\\r\\n            <li>Unplanned server outages, hosting provider incidents, or network disruptions</li>\\r\\n            <li>Power or connectivity failures at county government infrastructure</li>\\r\\n            <li>Cyber security incidents or denial-of-service attacks</li>\\r\\n            <li>Force majeure events</li>\\r\\n          </ul>\\r\\n          <p>Critical official communications will always be made available through alternative official channels including county government offices, the Kenya Gazette, and official press releases, in addition to this website.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-media\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">9</span> Media &amp; Photography</h2>\\r\\n          <p>Photographs, videos, and visual media published on this website may depict work in progress and do not represent the final completed state of any housing development. Specific limitations include:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Images are selected for illustrative purposes and may not represent the specific unit or block you are enquiring about</li>\\r\\n            <li>Architectural renders and 3D visualisations are artist&rsquo;s impressions only; final completed designs may differ from renders shown</li>\\r\\n            <li>Photographs of individuals on construction sites are used with consent and do not constitute endorsement of any product or service</li>\\r\\n            <li>Before-and-after imagery comparisons may not be from the same vantage point or lighting conditions and should not be used as precise progress evidence</li>\\r\\n          </ul>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-liability\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">10</span> Limitation of Liability</h2>\\r\\n          <p>Trans-Nzoia County Government, its officers, employees, contractors, and agents shall not be liable for any loss, damage, or harm arising from:</p>\\r\\n          <ul class=\\\"lg-list\\\">\\r\\n            <li>Reliance on any information, data, or content published on this website</li>\\r\\n            <li>Decisions made on the basis of information found on this website without independent verification</li>\\r\\n            <li>Website unavailability, data errors, or technical failures</li>\\r\\n            <li>Any action taken by any third party as a result of information published on this website</li>\\r\\n          </ul>\\r\\n          <p>To the fullest extent permitted by the laws of Kenya, all implied warranties, conditions, and representations are excluded. Nothing in this disclaimer limits liability for death or personal injury caused by negligence, or for fraudulent misrepresentation.</p>\\r\\n          <p>For a full statement of limitations, please also review our <a href=\\\"terms.php\\\">Terms of Use</a>.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-changes\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">11</span> Changes to This Disclaimer</h2>\\r\\n          <p>This Disclaimer may be updated from time to time to reflect changes in the information we publish, our operational practices, or applicable law. Material changes will be notified via a notice on the homepage for at least 14 days. The &ldquo;Last updated&rdquo; date at the top of this page will reflect the most recent revision.</p>\\r\\n          <p>We encourage you to review this Disclaimer periodically. Continued use of the website following publication of an updated Disclaimer constitutes your acceptance of the revised version.</p>\\r\\n        </section>\\r\\n\\r\\n        <section class=\\\"lg-section\\\" id=\\\"ds-contact\\\">\\r\\n          <h2 class=\\\"lg-section-heading\\\"><span class=\\\"lg-section-num\\\">12</span> Contact</h2>\\r\\n          <p>If you believe information on this website is inaccurate, misleading, or requires correction, or if you have questions about this Disclaimer, please contact us:</p>\\r\\n          <div class=\\\"lg-data-card\\\">\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Entity</span><span class=\\\"lg-data-val\\\">Trans-Nzoia County Government</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Department</span><span class=\\\"lg-data-val\\\">Department of Land, Housing &amp; Physical Planning</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Address</span><span class=\\\"lg-data-val\\\">County Headquarters, Kitale, Trans-Nzoia County, Kenya</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Phone</span><span class=\\\"lg-data-val\\\">+254 53 000 0000</span></div>\\r\\n            <div class=\\\"lg-data-row\\\"><span class=\\\"lg-data-key\\\">Email</span><span class=\\\"lg-data-val\\\">housing@transnzoia.go.ke</span></div>\\r\\n          </div>\\r\\n          <p>Data accuracy issues specifically may be reported to the Data Protection Officer at <strong>dpo@transnzoia.go.ke</strong>.</p>\\r\\n        </section>\\r\\n\\r\\n        <div class=\\\"lg-doc-footer\\\">\\r\\n          <p>This Disclaimer was last reviewed and approved by the Trans-Nzoia County Government Legal Services Unit on <strong>1 January 2026</strong>. Document reference: <code>TNZ-DISC-2026-01</code>.</p>\\r\\n          <div class=\\\"lg-doc-nav\\\">\\r\\n            <a href=\\\"privacy.php\\\" class=\\\"lg-doc-nav-link\\\"><i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Privacy Policy</a>\\r\\n            <a href=\\\"terms.php\\\" class=\\\"lg-doc-nav-link\\\"><i class=\\\"fa-solid fa-arrow-right\\\" aria-hidden=\\\"true\\\"></i> Terms of Use</a>\\r\\n          </div>\\r\\n        </div>\"}', NULL, '2026-05-27 13:31:48');

