(1, 'Cherangany', 'cherangany', NULL, NULL, 'Cherangany Constituency is the agricultural heartland of Trans-Nzoia. The Matunda AHP Estate serves farming communities along the Matunda-Sinyerere corridor.', 152000, 200, 1, 35, 'active', 'uploads/gallery/matunda-ahp-1.jpg', '2026-05-26 09:58:02', '2026-05-26 17:28:14'),
(2, 'Saboti', 'saboti', NULL, NULL, 'Saboti Constituency is home to the county headquarters, Kitale town, and hosts the flagship Maili Tatu AHP Estate - the largest affordable housing project in Trans-Nzoia County with 1,040 mixed-typology units.', 165000, 1120, 2, 58, 'active', 'uploads/gallery/maili-tatu-2.jpg', '2026-05-26 09:58:02', '2026-05-26 17:28:14'),
(3, 'Kiminini', 'kiminini', NULL, NULL, 'Kiminini Constituency has two housing projects in the planning and pre-construction stages, targeting delivery by 2028 through the National AHP Fund and County Development Fund.', 138000, 120, 2, 5, 'planning', NULL, '2026-05-26 09:58:02', '2026-05-26 17:28:15'),
(4, 'Kwanza', 'kwanza', NULL, NULL, 'Kwanza Constituency housing project is in architectural design review, with a Q4 2026 construction start targeted - delivering 80 affordable units in Kwanza town.', 112000, 80, 1, 8, 'planning', NULL, '2026-05-26 09:58:02', '2026-05-26 17:28:15'),
(5, 'Endebess', 'endebess', NULL, NULL, 'Endebess Constituency borders Uganda at the Suam crossing. Two active projects bring affordable housing to this strategic border region, including the Suam Border Post Estate.', 104000, 210, 2, 10, 'active', 'uploads/gallery/suam-ahp.jpg', '2026-05-26 09:58:02', '2026-05-26 17:28:15');

