INSERT INTO `faq_items` (`id`, `question`, `answer`, `category`, `sort_order`, `is_visible`) VALUES
(82, 'Who is eligible to apply for an affordable housing unit?', '<p>To be eligible, you must be a <strong>Kenyan citizen</strong> who:</p>\r\n                  <ul>\r\n                    <li>Is <strong>18 years of age or older</strong></li>\r\n                    <li>Has a valid <strong>National ID or Passport</strong></li>\r\n                    <li>Has a <strong>KRA PIN</strong> (required for levy deductions and eCitizen registration)</li>\r\n                    <li>Does <strong>not</strong> already own a residential property in Kenya</li>\r\n                    <li>Falls within the defined <strong>income brackets</strong> (Social Housing: below KSh 19,999/month; Affordable: KSh 20,000â€“149,999/month)</li>\r\n                  </ul>\r\n                  <p>Priority is given to civil servants, teachers, nurses, uniformed service personnel, persons with disabilities (PWD), and widowed or single-parent households.</p>', 'eligibility', 1, 1),
(83, 'Is there special consideration for persons with disabilities (PWD)?', '<p>Yes. The Affordable Housing Programme reserves <strong>at least 5% of all units</strong> in every development for persons with disabilities. PWD applicants must provide a <strong>National Council for Persons with Disabilities (NCPWD) certificate</strong> at the point of application.</p>\r\n                  <p>In Trans-Nzoia, ground-floor accessible units with widened doorways and adapted bathroom fittings are included in the Maili Tatu Estate design.</p>', 'eligibility', 2, 1),
(84, 'Can Kenyans in the diaspora apply?', '<p>Yes, Kenyans living and working abroad may apply through eCitizen using their Kenyan National ID or Passport. The <strong>Housing Levy</strong> for diaspora applicants is calculated based on self-declared income and must be remitted voluntarily via eCitizen or a participating bank.</p>', 'eligibility', 3, 1),
(85, 'Can I apply if I already own land but not a house?', '<p>Owning a <strong>plot of land</strong> does not automatically disqualify you. The restriction is on <strong>existing residential property</strong>. If you own land but have no habitable structure on it, you may still qualify, subject to income verification. However, owning a house â€” regardless of its size or location â€” disqualifies you from the Social Housing category.</p>', 'eligibility', 4, 1),
(86, 'How do I apply for an affordable housing unit?', '<p>Applications are made through <strong>eCitizen</strong> at <a href=\"https://ecitizen.go.ke\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fq-link\">ecitizen.go.ke</a>. The process is:</p>\r\n                  <ol>\r\n                    <li>Log in to eCitizen with your National ID and phone number</li>\r\n                    <li>Navigate to <strong>Ministry of Lands &amp; Housing â†’ Affordable Housing â†’ Apply for Unit</strong></li>\r\n                    <li>Complete the household income declaration form</li>\r\n                    <li>Upload required documents (ID, KRA PIN, payslip or bank statement)</li>\r\n                    <li>Select your preferred constituency in Trans-Nzoia</li>\r\n                    <li>Submit and retain your <strong>Application Reference Number</strong></li>\r\n                  </ol>\r\n                  <p>You will receive an SMS and email confirmation within 24 hours. Shortlisted applicants are contacted for biometric verification.</p>', 'application', 5, 1),
(87, 'What documents do I need to apply?', '<p>Required documents include:</p>\r\n                  <ul>\r\n                    <li>Copy of your <strong>National Identity Card</strong> (both sides)</li>\r\n                    <li><strong>KRA PIN Certificate</strong></li>\r\n                    <li>Recent <strong>payslip</strong> (last 3 months) <em>or</em> certified bank statements</li>\r\n                    <li><strong>Employment letter</strong> from your employer (for formal sector workers)</li>\r\n                    <li>For self-employed applicants: <strong>business permit</strong> and audited accounts or sworn affidavit of income</li>\r\n                    <li>NCPWD certificate (PWD applicants only)</li>\r\n                    <li>Death certificate of spouse (widowed applicants claiming priority)</li>\r\n                  </ul>', 'application', 6, 1),
(88, 'Is there a fee to submit an application?', '<p><strong>No application fee is charged.</strong> The application process through eCitizen is entirely free. Be wary of any individual or agent claiming to charge a processing fee â€” this is fraudulent. Report such cases to the AHB field office or through the <a href=\"contact.php\" class=\"fq-link\">Contact Us</a> page.</p>', 'application', 7, 1),
(89, 'How do I track the status of my application?', '<p>You can track your application status by:</p>\r\n                  <ul>\r\n                    <li>Logging into <strong>eCitizen</strong> and navigating to \"My Applications\" under the Housing module</li>\r\n                    <li>Calling the <strong>AHB Call Centre</strong> at 0800 723 133 (toll-free) with your reference number</li>\r\n                    <li>Visiting the <strong>AHB Field Office</strong> in Kitale (Ardhi House, off Moi Avenue)</li>\r\n                    <li>Checking for SMS/email updates linked to your registered phone number and email</li>\r\n                  </ul>', 'application', 8, 1),
(90, 'What is the Affordable Housing Levy and how much is it?', '<p>The <strong>Affordable Housing Levy</strong> is a statutory contribution introduced under the <em>Affordable Housing Act, 2024</em>. Every employed person contributes:</p>\r\n                  <ul>\r\n                    <li><strong>Employee:</strong> 1.5% of gross monthly salary</li>\r\n                    <li><strong>Employer:</strong> A matching 1.5% of the employee\'s gross monthly salary</li>\r\n                  </ul>\r\n                  <p>For a gross salary of <strong>KSh 50,000</strong>, the employee contribution is <strong>KSh 750/month</strong>, with the employer contributing an equal amount. Contributions are remitted to the Kenya Revenue Authority (KRA) alongside PAYE.</p>\r\n                  <p>Self-employed individuals pay a <strong>voluntary contribution</strong> of 1.5% of their declared income via eCitizen or Paybill <strong>222222</strong>.</p>', 'payments', 9, 1),
(91, 'Will I get a refund if I am not allocated a unit?', '<p>Yes. Under Section 28 of the Affordable Housing Act, levy contributions that do not result in unit allocation within <strong>15 years</strong> are refundable with interest. Additionally, if you choose to withdraw from the programme, you can apply for a refund at the AHB offices after a <strong>mandatory 3-year contribution period</strong>. Interest is accrued at the prevailing Treasury bond rate.</p>', 'payments', 10, 1),
(92, 'What are the monthly mortgage repayments after allocation?', '<p>After unit allocation, beneficiaries pay a subsidised mortgage through the <strong>Kenya Mortgage Refinance Company (KMRC)</strong>. Typical monthly repayments are:</p>\r\n                  <ul>\r\n                    <li><strong>1-bedroom unit</strong> (approx. KSh 1.5M): ~KSh 7,000â€“9,000/month over 25 years at 7% p.a.</li>\r\n                    <li><strong>2-bedroom unit</strong> (approx. KSh 2.5M): ~KSh 12,000â€“15,000/month over 25 years at 7% p.a.</li>\r\n                    <li><strong>3-bedroom unit</strong> (approx. KSh 4.0M): ~KSh 18,000â€“22,000/month over 25 years at 7% p.a.</li>\r\n                  </ul>\r\n                  <p>Accumulated Housing Levy contributions are applied as a <strong>deposit</strong>, reducing the principal and therefore the monthly amount. Exact figures are confirmed at the point of allocation.</p>', 'payments', 11, 1),
(93, 'How are housing units allocated to applicants?', '<p>Unit allocation follows a <strong>transparent balloting process</strong> overseen by the Affordable Housing Board (AHB) and supervised by a neutral public officer. The steps are:</p>\r\n                  <ol>\r\n                    <li><strong>Shortlisting</strong> â€” all verified applicants within the income bracket for the specific development are shortlisted</li>\r\n                    <li><strong>Priority sorting</strong> â€” PWD, civil servants, teachers, nurses, and widows/widowers get priority slots (reserved at least 30%)</li>\r\n                    <li><strong>Open ballot</strong> â€” remaining units are allocated by public ballot. Results are published on eCitizen and at the AHB field offices</li>\r\n                    <li><strong>Offer letter</strong> â€” successful applicants receive a formal offer letter via email and SMS</li>\r\n                    <li><strong>Acceptance &amp; deposit</strong> â€” applicants must formally accept and pay the first instalment within 30 days</li>\r\n                  </ol>', 'allocation', 12, 1),
(94, 'What if I am not selected in the ballot?', '<p>Unsuccessful applicants are placed on a <strong>waiting list</strong> and automatically considered for future developments without re-applying. Your position in the waiting list improves with each ballot cycle based on the length of your contribution period. You will receive notification via eCitizen when the next allocation round opens.</p>', 'allocation', 13, 1),
(95, 'Can I choose the type of unit (1BR, 2BR, 3BR)?', '<p>Yes. During the application process you indicate your <strong>preferred unit type and size</strong>. However, final allocation depends on availability of your preferred type in the development assigned to your constituency. Where your first preference is unavailable, you may be offered an alternative type or held on the waiting list for the preferred type in the next phase.</p>', 'allocation', 14, 1),
(96, 'When will construction be completed and units handed over?', '<p>Completion timelines vary by site. Current projections are:</p>\r\n                  <ul>\r\n                    <li><strong>Maili Tatu Estate (Kiminini):</strong> Phase 1 â€” 400 units, targeted completion <strong>Q4 2026</strong></li>\r\n                    <li><strong>Matunda AHP (TN West):</strong> 200 units, targeted completion <strong>Q2 2027</strong></li>\r\n                    <li><strong>Saboti AHP:</strong> 300 units, targeted completion <strong>Q3 2027</strong></li>\r\n                    <li><strong>Kwanza AHP:</strong> 250 units, design phase ongoing, construction start <strong>Q1 2026</strong></li>\r\n                    <li><strong>TN East (Cherang\'any):</strong> Land allocation finalised, tender advertised <strong>2026</strong></li>\r\n                  </ul>\r\n                  <p>All timelines are subject to contractor performance, funding releases, and NCA certification. Check the <a href=\"projects.php\" class=\"fq-link\">Projects page</a> for live updates.</p>', 'construction', 15, 1),
(97, 'Who checks the quality of construction?', '<p>Construction quality is overseen by multiple independent bodies:</p>\r\n                  <ul>\r\n                    <li><strong>National Construction Authority (NCA)</strong> â€” quarterly structural inspections and site occupancy certification</li>\r\n                    <li><strong>National Environment Management Authority (NEMA)</strong> â€” environmental compliance oversight</li>\r\n                    <li><strong>AHB Project Management Unit (PMU)</strong> â€” monthly progress certification before contractor payment</li>\r\n                    <li><strong>County Department of Physical Planning</strong> â€” building plan approvals and compliance checks</li>\r\n                    <li><strong>Independent structural engineers</strong> â€” engaged by AHB for third-party verification</li>\r\n                  </ul>', 'construction', 16, 1),
(98, 'Can I visit the construction site to see progress?', '<p>General public access to active construction sites is restricted for <strong>safety reasons</strong>. However, the AHB Field Office organises <strong>quarterly open days</strong> where vetted applicants and the public can visit specific zones under supervision. These are announced on the AHB website, eCitizen, and through this platform\'s <a href=\"news.php\" class=\"fq-link\">News page</a>.</p>\r\n                  <p>Real-time progress is also documented in the <a href=\"gallery.php\" class=\"fq-link\">Photo Gallery</a> and on the <a href=\"projects.php\" class=\"fq-link\">Projects page</a>.</p>', 'construction', 17, 1),
(99, 'Will I receive a title deed for my unit?', '<p>Yes. Upon full payment of the purchase price, beneficiaries receive a <strong>Certificate of Title (Sectional Title)</strong> under the Land Registration Act, 2012. For mortgage holders, the title is held by the lender (KMRC or bank) as security and is released upon full loan repayment. The Sectional Title confers <strong>absolute ownership</strong> of the specific unit and a shared ownership interest in common areas.</p>', 'legal', 18, 1),
(100, 'Can I sell or rent out my unit?', '<p>Resale and subletting restrictions apply for the first <strong>5 years</strong> from the date of handover. During this period, you may not sell, assign, or sublet the unit without written AHB approval. After 5 years, the unit is fully yours to sell or rent at market rates. Any sale during the restricted period must be reported to AHB and is subject to a <strong>claw-back provision</strong> on the government subsidy.</p>', 'legal', 19, 1),
(101, 'What rights do I have as an AHP applicant?', '<p>As an AHP applicant you have the right to:</p>\r\n                  <ul>\r\n                    <li>A <strong>free, fair and transparent</strong> application and balloting process</li>\r\n                    <li>Access and inspect the <strong>levy statement</strong> showing your cumulative contributions at any time via eCitizen</li>\r\n                    <li>Receive a <strong>formal offer letter</strong> and sale agreement before making any payment</li>\r\n                    <li>Lodge a <strong>complaint or appeal</strong> against any allocation decision within 30 days of notification</li>\r\n                    <li>A <strong>refund</strong> of levy contributions with interest as provided under the Act</li>\r\n                    <li>Not be discriminated against on the basis of <strong>ethnicity, religion, gender or disability</strong></li>\r\n                  </ul>', 'rights', 20, 1),
(102, 'How do I report fraud or corruption related to the programme?', '<p>Report any suspected fraud, bribery or corruption through:</p>\r\n                  <ul>\r\n                    <li><strong>Ethics and Anti-Corruption Commission (EACC):</strong> <a href=\"tel:0800720650\" class=\"fq-link\">0800 720 650</a> (toll-free) or <a href=\"https://eacc.go.ke\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fq-link\">eacc.go.ke</a></li>\r\n                    <li><strong>AHB Tip-off Line:</strong> <a href=\"tel:0800723133\" class=\"fq-link\">0800 723 133</a></li>\r\n                    <li><strong>County Ombudsman:</strong> Trans-Nzoia County offices, Kitale</li>\r\n                    <li>Through this platform\'s <a href=\"contact.php\" class=\"fq-link\">Contact page</a> (all submissions are confidential)</li>\r\n                  </ul>', 'rights', 21, 1),
(103, 'Where is the AHB Field Office in Trans-Nzoia?', '<p>The AHB Field Office for Trans-Nzoia County is located at:</p>\r\n                  <address class=\"fq-address\">\r\n                    <strong>Ardhi House, Moi Avenue</strong><br>\r\n                    Near the County Commissioner\'s Premises<br>\r\n                    Kitale, Trans-Nzoia County<br><br>\r\n                    <strong>Office hours:</strong> Mondayâ€“Friday, 8:00amâ€“5:00pm<br>\r\n                    <strong>Phone:</strong> <a href=\"tel:+254530000000\" class=\"fq-link\">+254 53 000 0000</a><br>\r\n                    <strong>Email:</strong> <a href=\"mailto:housing@transnzoia.go.ke\" class=\"fq-link\">housing@transnzoia.go.ke</a>\r\n                  </address>', 'contact', 22, 1),
(104, 'Is there a national AHP helpline?', '<p>Yes. The <strong>Affordable Housing Board national helpline</strong> is:</p>\r\n                  <ul>\r\n                    <li><strong>Toll-free:</strong> <a href=\"tel:0800723133\" class=\"fq-link\">0800 723 133</a> (available Monâ€“Fri, 8amâ€“6pm)</li>\r\n                    <li><strong>WhatsApp:</strong> <a href=\"https://wa.me/254700000000\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fq-link\">0700 000 000</a></li>\r\n                    <li><strong>Email:</strong> <a href=\"mailto:info@affordablehousing.go.ke\" class=\"fq-link\">info@affordablehousing.go.ke</a></li>\r\n                    <li><strong>Website:</strong> <a href=\"https://affordablehousing.go.ke\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"fq-link\">affordablehousing.go.ke</a></li>\r\n                  </ul>', 'contact', 23, 1);

