INSERT INTO `news_articles` (`id`, `category_id`, `author_id`, `title`, `slug`, `excerpt`, `read_time`, `body`, `featured_image_id`, `image_caption`, `inline_image_id`, `status`, `is_featured`, `published_at`, `scheduled_for`, `views`, `seo_title`, `seo_description`, `og_image_id`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate - Beneficiaries Receive Keys', 'maili-tatu-first-200-units', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', '6 min read', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', 8, NULL, NULL, 'published', 1, '2026-05-15 08:00:00', NULL, 0, 'Trans-Nzoia AHP Delivers First 200 Units at Maili Tatu Estate - Beneficiaries Receive Keys', 'In a landmark ceremony held at the Maili Tatu Estate in Kitale, Governor George Natembeya presided over the handover of 200 affordable housing units to qualifying beneficiaries. The milestone marks a significant step in the county commitment to delivering dignified, affordable housing to low- and middle-income residents under the national AHP framework.', NULL, '2026-05-26 17:30:02', '2026-05-26 17:30:02'),
(2, 32, 1, 'Ground-Breaking Ceremony Marks Start of Endebess Phase 2 Construction', 'endebess-phase-2-groundbreaking', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', '3 min', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', 9, NULL, NULL, 'published', 0, '2026-05-10 08:00:00', NULL, 0, 'Ground-Breaking Ceremony Marks Start of Endebess Phase 2 Construction', 'County officials and community leaders gathered at the Endebess site to officially launch the second phase of the affordable housing project, set to deliver 120 additional units to qualifying residents.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(3, 33, 1, 'Cherangany Housing Project Reaches 70% Completion Milestone', 'cherangany-70-percent-completion', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', '4 min', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', 10, NULL, NULL, 'published', 0, '2026-05-08 08:00:00', NULL, 0, 'Cherangany Housing Project Reaches 70% Completion Milestone', 'The Cherangany constituency AHP project has surpassed the 70% completion threshold, with roofing works now underway on the final two residential blocks ahead of the projected Q3 2026 handover date.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(4, 34, 1, 'County Receives KSh 1.8 Billion National AHP Allocation for FY 2026/27', 'fy-2026-27-ahp-allocation', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', '5 min', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', 11, NULL, NULL, 'published', 0, '2026-05-05 08:00:00', NULL, 0, 'County Receives KSh 1.8 Billion National AHP Allocation for FY 2026/27', 'The National Treasury has confirmed a KSh 1.8 billion disbursement to Trans-Nzoia County under the Affordable Housing Programme for the upcoming financial year, enabling the commencement of three new estate projects.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(5, 35, 1, 'Community Stakeholders Forum Held in Kwanza Sub-County', 'kwanza-community-stakeholders-forum', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', '3 min', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', 12, NULL, NULL, 'published', 0, '2026-05-03 08:00:00', NULL, 0, 'Community Stakeholders Forum Held in Kwanza Sub-County', 'Over 400 residents attended the public participation forum in Kwanza, where the Housing Department presented the beneficiary registration process, eligibility criteria, and construction timelines for the local AHP estate.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(6, 36, 1, 'Governor Issues Statement on Beneficiary Selection and Allocation Criteria', 'beneficiary-selection-statement', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', '2 min', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', 13, NULL, NULL, 'published', 0, '2026-05-01 08:00:00', NULL, 0, 'Governor Issues Statement on Beneficiary Selection and Allocation Criteria', 'The Office of the Governor has released an official statement clarifying the eligibility criteria for affordable housing unit allocation, reaffirming that selection will be transparent, needs-based, and verifiable through public registers.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(7, 37, 1, 'Field Report: Site Visit to Kiminini Social Housing Complex', 'kiminini-site-field-report', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', '5 min', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', 14, NULL, NULL, 'published', 0, '2026-04-28 08:00:00', NULL, 0, 'Field Report: Site Visit to Kiminini Social Housing Complex', 'County housing inspectors conducted a comprehensive site assessment at the Kiminini Social Housing Complex, confirming structural compliance on all four residential blocks and certifying the plumbing installations on Blocks A and B.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(8, 1, 1, 'National Housing Corporation Signs New Implementation Agreement with Trans-Nzoia County', 'nhc-implementation-agreement', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', '4 min', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', 15, NULL, NULL, 'published', 0, '2026-04-25 08:00:00', NULL, 0, 'National Housing Corporation Signs New Implementation Agreement with Trans-Nzoia County', 'The National Housing Corporation and Trans-Nzoia County Government have signed a revised implementation agreement expanding the scope of the AHP programme to include two additional estate sites in Saboti and Kwanza constituencies.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(9, 35, 1, 'Residents Urged to Register Beneficiary Interest via eCitizen Portal', 'ecitizen-beneficiary-registration', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', '3 min', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', 16, NULL, NULL, 'published', 0, '2026-04-22 08:00:00', NULL, 0, 'Residents Urged to Register Beneficiary Interest via eCitizen Portal', 'The Department of Land, Housing and Physical Planning has called on all eligible Trans-Nzoia residents to formally register their interest for affordable housing units through the government eCitizen online portal before the 30 June 2026 deadline.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(10, 34, 1, 'New Affordable Housing Allocation Policy Framework Released for Public Input', 'allocation-policy-framework', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', '6 min', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', 17, NULL, NULL, 'published', 0, '2026-04-18 08:00:00', NULL, 0, 'New Affordable Housing Allocation Policy Framework Released for Public Input', 'The County Assembly Housing Committee has published a draft allocation policy framework for public comment, outlining income bands, household size requirements, and priority scoring for first-time homeowners under the AHP.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(11, 33, 1, 'Saboti Constituency: First 50 Housing Units Ready for Beneficiary Handover', 'saboti-first-50-handover-ready', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', '4 min', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', 18, NULL, NULL, 'published', 0, '2026-04-15 08:00:00', NULL, 0, 'Saboti Constituency: First 50 Housing Units Ready for Beneficiary Handover', 'Engineers have issued practical completion certificates for the first 50 units at the Saboti AHP estate following final electrical, plumbing, and structural sign-offs, clearing the way for the formal handover ceremony scheduled for May 2026.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(12, 35, 1, '300 Local Youth Artisans Employed Across Trans-Nzoia AHP Construction Sites', 'local-youth-artisans-employed', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', '3 min', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', 19, NULL, NULL, 'published', 0, '2026-04-12 08:00:00', NULL, 0, '300 Local Youth Artisans Employed Across Trans-Nzoia AHP Construction Sites', 'A county-led youth employment initiative has placed over 300 trained artisans - including masons, carpenters, and electricians - on active AHP construction sites, aligning housing delivery with local economic empowerment goals.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03'),
(13, 1, 1, 'AHP Programme Update: 1,200 Units Under Active Construction County-Wide', 'programme-update-1200-active-units', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', '5 min', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', 20, NULL, NULL, 'published', 0, '2026-04-08 08:00:00', NULL, 0, 'AHP Programme Update: 1,200 Units Under Active Construction County-Wide', 'The latest quarterly programme report confirms that 1,200 affordable housing units are now under active construction across all five constituencies in Trans-Nzoia County, representing a 40% increase on the previous quarter figures.', NULL, '2026-05-26 17:30:03', '2026-05-26 17:30:03');

