(15, 1, 2, 152, 'Maili Tatu Affordable Housing Estate', 'maili-tatu-estate', 'Saboti, Matisi Ward', 'active', 60, NULL, '2024-01-01', '2026-01-01', 'Roofing works - Block E & F', 'Jabavu Developers Ltd', NULL, NULL, 'The flagship affordable housing project in Trans-Nzoia County, located on the outskirts of Kitale town in Matisi Ward. The estate features 1,040 mixed-typology units across 8 residential blocks - studios, one-bedroom and two-bedroom apartments targeting low-to-middle-income earners registered on the Boma Yangu portal.', 'uploads/gallery/maili-tatu-1.jpg', '[\"uploads/gallery/maili-tatu-1.jpg\",\"uploads/gallery/maili-tatu-2.jpg\",\"uploads/gallery/maili-tatu-3.jpg\"]', 'National AHP Fund', 'State Dept. of Housing', 'Eng. S. K. Kariuki', 1040, 1, '2026-05-26 17:28:44', '2026-05-26 17:51:29'),
(24, 1, 2, 153, 'Kitale Town Infill Units', 'kitale-infill-units', 'Saboti, Kitale Central', 'active', 55, NULL, '2024-01-01', '2027-01-01', 'Internal finishing - Blocks A & B', 'BuildRight Construction Co.', NULL, NULL, 'Urban infill development within Kitale town centre targeting low-income households in proximity to employment centres, schools and healthcare facilities. 80 one- and two-bedroom units spread across 4 blocks.', 'uploads/gallery/kitale-ex-prison.jpeg', '[\"uploads/gallery/kitale-ex-prison.jpeg\"]', 'County Development Fund', 'Trans-Nzoia County Housing Dept.', 'Eng. P. Wafula', 80, 1, '2026-05-26 17:29:20', '2026-05-26 17:51:29'),
